#!/usr/bin/env python3
"""Unit P3 acceptance 1: every `--flag` in the five skills resolves against `db.py <verb> --help`
(or the named script's --help).  Fenced blocks are parsed per command (verb known exactly);
inline backticked tokens are checked against the verb named in the token, else the nearest
preceding verb/script named in the same paragraph, else the union (reported as UNION-ONLY).
Usage: flagcheck.py [files...]   (default: the five skills)"""
import re
import subprocess
import sys
from functools import lru_cache
from pathlib import Path

REPO = Path("/home/user/guidebook")
FILES = [f"skills/{n}_SKILL.md" for n in (
    "run-pipeline", "connection-discovery", "cross-population-conflict-mapper",
    "research-log-manager", "citation-miner")]
FLAG = re.compile(r"(?<![\w-])(--[a-z][a-z0-9-]*)")


def run_help(args):
    r = subprocess.run([sys.executable, *args, "--help"], cwd=REPO, capture_output=True, text=True)
    return r.stdout + r.stderr


@lru_cache(None)
def verbs():
    h = run_help(["scripts/db.py"])
    m = re.search(r"\{([a-z0-9,-]+)\}", h)
    return m.group(1).split(",")


@lru_cache(None)
def verb_flags(v):
    return set(FLAG.findall(run_help(["scripts/db.py", v])))


@lru_cache(None)
def script_flags(path):
    if not (REPO / path).exists():
        return None
    return set(FLAG.findall(run_help([path])))


SCRIPT = re.compile(r"((?:scripts/[\w/]+|\.claude/hooks/[\w-]+)\.(?:py|sh))")
VERB_RE = None


def verb_names():
    global VERB_RE
    if VERB_RE is None:
        VERB_RE = re.compile(r"(?<![\w-])(" + "|".join(sorted(map(re.escape, verbs()), key=len, reverse=True)) + r")(?![\w-])")
    return VERB_RE


def ctx_target(text, pos):
    """nearest preceding verb or script name, looking back within the paragraph"""
    start = text.rfind("\n\n", 0, pos) + 1
    seg = text[max(start, pos - 400):pos]
    best = None
    for m in verb_names().finditer(seg):
        best = ("verb", m.group(1), m.start())
    for m in SCRIPT.finditer(seg):
        if best is None or m.start() > best[2]:
            best = ("script", m.group(1), m.start())
    return best


def check_file(rel):
    text = (REPO / rel).read_text()
    out = []
    # fenced blocks
    spans = []
    for m in re.finditer(r"```[^\n]*\n(.*?)```", text, re.S):
        spans.append((m.start(), m.end()))
        block = m.group(1)
        # strip comments, join continuations
        lines = []
        for ln in block.split("\n"):
            ln2 = re.sub(r"\s+#.*$", "", ln) if not ln.lstrip().startswith("#") else ""
            lines.append(ln2)
        joined = re.sub(r"\\\s*\n", " ", "\n".join(lines))
        for cmd in joined.split("\n"):
            mv = re.search(r"scripts/db\.py\s+([a-z0-9-]+)", cmd)
            if mv and mv.group(1) in verbs():
                v = mv.group(1)
                for f in FLAG.findall(cmd[mv.end():]):
                    if f not in verb_flags(v) and f != "--help":
                        out.append((rel, "fence", f"db.py {v}", f, "NOT IN --help"))
                continue
            ms = SCRIPT.search(cmd)
            if ms:
                sf = script_flags(ms.group(1))
                if sf is None:
                    continue
                for f in FLAG.findall(cmd[ms.end():]):
                    if f not in sf and f != "--help":
                        out.append((rel, "fence", ms.group(1), f, "NOT IN --help"))
    # inline
    for m in re.finditer(r"`([^`\n]+)`", text):
        if any(s <= m.start() < e for s, e in spans):
            continue
        tok = m.group(1)
        flags = FLAG.findall(tok)
        if not flags:
            continue
        mv = re.match(r"(?:db\.py\s+|scripts/db\.py\s+)?([a-z0-9-]+)\s", tok)
        explicit = mv.group(1) if mv and mv.group(1) in verbs() else None
        ms = SCRIPT.search(tok)
        tgt = ("verb", explicit, 0) if explicit else (("script", ms.group(1), 0) if ms else ctx_target(text, m.start()))
        for f in flags:
            if tgt and tgt[0] == "verb":
                if f in verb_flags(tgt[1]):
                    continue
                accept = [v for v in verbs() if f in verb_flags(v)]
                out.append((rel, "inline", f"ctx verb {tgt[1]}", f,
                            "NOT IN ctx verb; accepted by: " + (",".join(accept) or "NO VERB")))
            elif tgt and tgt[0] == "script":
                sf = script_flags(tgt[1])
                if sf is not None and f in sf:
                    continue
                accept = [v for v in verbs() if f in verb_flags(v)]
                out.append((rel, "inline", f"ctx script {tgt[1]}", f,
                            "NOT IN script; db.py verbs: " + (",".join(accept) or "NONE")))
            else:
                accept = [v for v in verbs() if f in verb_flags(v)]
                if not accept:
                    out.append((rel, "inline", "no ctx", f, "NO VERB ACCEPTS"))
                else:
                    out.append((rel, "inline", "no ctx", f, "UNION-ONLY: " + ",".join(accept)))
    return out


def main():
    files = sys.argv[1:] or FILES
    allout = []
    for f in files:
        allout += check_file(f)
    hard = [o for o in allout if "UNION-ONLY" not in o[4]]
    soft = [o for o in allout if "UNION-ONLY" in o[4]]
    for o in hard:
        print("MISMATCH", " | ".join(o))
    for o in soft:
        print("UNION-ONLY(review)", " | ".join(o))
    print(f"files={len(files)} mismatches={len(hard)} union-only={len(soft)}")


main()

